<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { useRoute } from 'vue-router'
import { ElMessage } from 'element-plus'
import { knowledgeApi, type KnowledgeCategory, type KnowledgeDocument, type KnowledgeSearch, type KnowledgeSave } from '../api/knowledge'
import { departmentApi, type Department } from '../api'
import { useAppShell } from '../layouts/appShell'
const shell=useAppShell(), route=useRoute()
const categories=ref<KnowledgeCategory[]>([]), documents=ref<KnowledgeDocument[]>([]), departments=ref<Department[]>([])
const editing=ref<KnowledgeDocument|null>(null), visible=ref(false), busy=ref(false), error=ref(''), chunks=ref<string[]>([])
const categoryOpen=ref(false), query=ref(''), searchProject=ref<string>(String(route.query.project_id || '')), result=ref<KnowledgeSearch|null>(null)
const category=reactive({name:'',scope:'PROJECT',project_id:searchProject.value,access_policy:'PROJECT_MEMBERS',department_id:''})
const form=reactive<KnowledgeSave>({title:'',category_id:'',content:'',expected_revision:0,settings:{separator:'\n\n',target_chars:600,overlap_chars:80},effective_from:null,effective_until:null})
const load=async()=>{[categories.value,documents.value]=await Promise.all([knowledgeApi.categories(),knowledgeApi.list()])}
const perform=async(action:()=>Promise<void>)=>{if(busy.value)return;busy.value=true;error.value='';try{await action()}catch(e){error.value=e instanceof Error?e.message:'操作失败'}finally{busy.value=false}}
const open=async(doc:KnowledgeDocument|null)=>{
 await perform(async()=>{editing.value=doc?await knowledgeApi.detail(doc.id):null;const v=editing.value?.versions[0];Object.assign(form,{title:doc?.title||'',category_id:doc?.category_id||categories.value[0]?.id||'',content:v?.content||'',expected_revision:editing.value?.revision||0,settings:v?.settings||{separator:'\n\n',target_chars:600,overlap_chars:80},effective_from:v?.effective_from||null,effective_until:v?.effective_until||null});chunks.value=[];visible.value=true})
}
const save=()=>perform(async()=>{editing.value=await knowledgeApi.save(editing.value?.id||null,form);form.expected_revision=editing.value.revision;await load();ElMessage.success('草稿已保存')})
const publish=()=>perform(async()=>{if(!editing.value)return;editing.value=await knowledgeApi.publish(editing.value.id,editing.value.revision);form.expected_revision=editing.value.revision;await load();const v=editing.value.versions[0];if(v?.status==='FAILED')error.value=v.error||'发布失败，旧版保留';else ElMessage.success('知识已发布')})
const upload=async(event:Event)=>{const file=(event.target as HTMLInputElement).files?.[0];if(file)await perform(async()=>{form.content=(await knowledgeApi.upload(file)).content})}
const createCategory=()=>perform(async()=>{await knowledgeApi.createCategory({...category,project_id:category.scope==='PROJECT'?category.project_id:null,department_id:category.scope==='ENTERPRISE'&&category.access_policy==='DEPARTMENT'?category.department_id:null,access_policy:category.scope==='PROJECT'?'PROJECT_MEMBERS':category.access_policy==='PROJECT_MEMBERS'?'ALL_MEMBERS':category.access_policy});categoryOpen.value=false;await load()})
onMounted(()=>{void perform(load);void departmentApi.list({page:1,page_size:100}).then(data=>{departments.value=data.items}).catch(()=>{})})
</script>
<template>
 <div class="knowledge-page">
  <div class="page-head"><div><h2>企业 / 项目知识库</h2><p>管理可追溯的有效知识，为 Coo 提供业务依据。</p></div><div><el-button @click="categoryOpen=true">新建分类</el-button><el-button type="primary" @click="open(null)">创建知识</el-button></div></div>
  <el-alert v-if="error" :title="error" type="error" :closable="false" />
  <el-table :data="documents" v-loading="busy"><el-table-column prop="title" label="知识标题"/><el-table-column label="范围"><template #default="{row}">{{ categories.find(c=>c.id===row.category_id)?.scope==='PROJECT'?'项目成员':'企业' }} · {{categories.find(c=>c.id===row.category_id)?.name}}</template></el-table-column><el-table-column prop="state" label="当前状态"/><el-table-column label="操作" width="270"><template #default="{row}"><el-button text @click="open(row)">编辑 / 版本</el-button><el-button text @click="perform(async()=>{await knowledgeApi.enable(row);await load()})">{{row.enabled?'停用':'启用'}}</el-button><el-button text @click="perform(async()=>{await knowledgeApi.restore(row);await load();ElMessage.success('上一版已恢复为新草稿，请检查后发布')})">恢复上一版</el-button></template></el-table-column></el-table>
  <section class="recall"><h3>召回测试</h3><p>只检索企业可访问知识和所选项目，展示本次实际命中的来源片段。</p><div class="search-row"><el-select v-model="searchProject" clearable placeholder="仅企业知识"><el-option v-for="p in shell.projects.value" :key="p.id" :label="p.name" :value="p.id"/></el-select><el-input v-model="query" placeholder="例如：订单超时未发货应该如何跟进？"/><el-button type="primary" :disabled="!query.trim()" :loading="busy" @click="perform(async()=>{result=await knowledgeApi.search(query,searchProject||null)})">测试召回</el-button></div><template v-if="result"><el-alert v-for="warning in result.warnings" :key="warning" :title="warning" type="warning" :closable="false"/><p>排序：{{result.score_kind}} · {{result.results.length}} 个片段</p><article v-for="source in result.results" :key="source.id"><strong>{{source.document_title}} · v{{source.version}}</strong><p>{{source.content}}</p><small>片段 {{source.id}} · 分数 {{source.score.toFixed(4)}}</small></article></template></section>
  <el-drawer v-model="visible" title="知识编辑与版本" size="650px"><el-form label-position="top"><el-form-item label="标题"><el-input v-model="form.title" maxlength="200"/></el-form-item><el-form-item label="知识分类（决定访问权限）"><el-select v-model="form.category_id" :disabled="!!editing"><el-option v-for="c in categories" :key="c.id" :label="`${c.scope==='PROJECT'?'项目':'企业'} · ${c.name}`" :value="c.id"/></el-select></el-form-item><el-form-item label="正文"><input type="file" accept=".txt,.md" @change="upload"/><el-input v-model="form.content" type="textarea" :rows="10"/></el-form-item><div class="search-row"><el-form-item label="切片长度"><el-input-number v-model="form.settings.target_chars" :min="100" :max="4000"/></el-form-item><el-form-item label="重叠长度"><el-input-number v-model="form.settings.overlap_chars" :min="0" :max="1000"/></el-form-item></div><el-form-item label="生效时间"><el-date-picker v-model="form.effective_from" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ" clearable/></el-form-item><el-form-item label="失效时间"><el-date-picker v-model="form.effective_until" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ" clearable/></el-form-item></el-form><el-alert v-if="error" :title="error" type="error"/><el-button :loading="busy" @click="perform(async()=>{chunks=(await knowledgeApi.preview(form.content,form.settings)).chunks})">分段预览</el-button><el-button :loading="busy" type="primary" :disabled="!form.title||!form.content||!form.category_id" @click="save">保存草稿</el-button><el-button :loading="busy" :disabled="!editing||editing.versions[0]?.status==='PUBLISHED'" @click="publish">发布已保存草稿</el-button><article v-for="(chunk,i) in chunks" :key="i"><small>片段 {{i+1}}</small><p>{{chunk}}</p></article><h3>版本历史</h3><article v-for="v in editing?.versions" :key="v.id">v{{v.version}} · {{v.status}}<p v-if="v.error">{{v.error}}（旧的有效发布版本继续保留）</p></article></el-drawer>
  <el-dialog v-model="categoryOpen" title="新建知识分类" width="500px"><el-form label-position="top"><el-form-item label="分类名称"><el-input v-model="category.name"/></el-form-item><el-form-item label="范围"><el-radio-group v-model="category.scope"><el-radio value="PROJECT">项目知识</el-radio><el-radio value="ENTERPRISE">企业知识（管理员维护）</el-radio></el-radio-group></el-form-item><el-form-item v-if="category.scope==='PROJECT'" label="所属项目"><el-select v-model="category.project_id"><el-option v-for="p in shell.projects.value" :key="p.id" :value="p.id" :label="p.name"/></el-select></el-form-item><template v-else><el-form-item label="访问策略"><el-select v-model="category.access_policy"><el-option value="ALL_MEMBERS" label="所有已登录员工"/><el-option value="DEPARTMENT" label="仅指定部门"/></el-select></el-form-item><el-form-item v-if="category.access_policy==='DEPARTMENT'" label="可访问部门"><el-select v-model="category.department_id"><el-option v-for="d in departments" :key="d.id" :value="d.id" :label="d.name"/></el-select></el-form-item></template></el-form><template #footer><el-button :loading="busy" type="primary" @click="createCategory">创建分类</el-button></template></el-dialog>
 </div>
</template>
<style scoped>
.knowledge-page{padding:28px;max-width:1300px;margin:auto}.page-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px}.page-head p,.recall>p{color:#8792a2}.recall{margin-top:32px}.search-row{display:flex;gap:12px;align-items:center}.search-row .el-select{min-width:200px}article{border:1px solid #e5e9f0;border-radius:8px;padding:16px;margin-top:12px}article p{white-space:pre-wrap;overflow-wrap:anywhere}small{color:#8b95a5}
</style>
